perl -e '
use strict; use warnings; binmode STDOUT;
my $exe = "/workspace/dataset/test4_executable";
my @cases = (
 ["default", undef],
 ["ascii", "example.com"],
 ["utf8_label", pack("H*", "62c3bc636865722e6465")],
 ["utf8_multibyte_mix", pack("H*", "e697a5e69cace8aa9ee381bfe38293e381aa2e6578616d706c65")],
 ["emoji", pack("H*", "6578f09f9880616d706c652e636f6d")],
 ["bom_prefix", pack("H*", "efbbbf6578616d706c652e636f6d")],
 ["bom_middle", pack("H*", "6578616d706c652eefbbbf636f6d")],
 ["zwsp", pack("H*", "6578e2808b616d706c652e636f6d")],
 ["zwnj", pack("H*", "6578e2808c616d706c652e636f6d")],
 ["zwj", pack("H*", "6578e2808d616d706c652e636f6d")],
 ["word_joiner", pack("H*", "6578e281a0616d706c652e636f6d")],
 ["combining", pack("H*", "65cc8178616d706c652e636f6d")],
 ["malformed_80", pack("H*", "657880616d706c652e636f6d")],
 ["malformed_ff", pack("H*", "6578ff616d706c652e636f6d")],
 ["malformed_c0", pack("H*", "6578c0af616d706c652e636f6d")],
 ["truncated_2", pack("H*", "6578c3616d706c652e636f6d")],
 ["truncated_3", pack("H*", "6578e282616d706c652e636f6d")],
 ["truncated_4", pack("H*", "6578f09f98616d706c652e636f6d")],
 ["lone_cont", pack("H*", "65788081616d706c652e636f6d")],
 ["surrogate_utf8", pack("H*", "6578eda080616d706c652e636f6d")],
 ["overlong_slash", pack("H*", "6578c0af616d706c652e636f6d")],
 ["too_high", pack("H*", "6578f4908080616d706c652e636f6d")],
);
for my $case (@cases) {
 my ($name,$arg)=@$case;
 my $display = defined($arg) ? unpack("H*",$arg) : "<none>";
 print "=== $name hex=$display\n";
 my @cmd = defined($arg) ? ($exe,$arg) : ($exe);
 open(my $fh, "-|", @cmd) or do { print "EXEC ERROR: $!\n"; next; };
 binmode $fh;
 print while <$fh>;
 close($fh);
 print "rc=" . ($? >> 8) . " signal=" . ($? & 127) . "\n" if $? != 0;
}
'

